// Every stop on the route is wired up: config present, subsystems resolve, photos and credits exist, talk points written.
import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync } from "node:fs";
import { tour, loadCars } from "./helpers.mjs";

const root = new URL("../../", import.meta.url);
const exists = p => existsSync(new URL(p, root));
const cars = await loadCars();

test("tour slugs are unique, safe and match their config", () => {
  assert.equal(new Set(tour.map(s => s.slug)).size, tour.length);
  tour.forEach((s, i) => {
    assert.match(s.slug, /^[a-z0-9-]+$/);
    assert.equal(cars[i].slug, s.slug);
    assert.ok(s.room && Number.isInteger(s.level), `${s.slug}: room and level`);
  });
});

for (const car of cars) {
  test(`${car.slug}: text, components and sources`, () => {
    for (const k of ["title", "name", "summary", "eyebrow", "lede", "note"]) assert.ok(car[k], `${k} missing`);
    assert.ok(Number.isInteger(car.year));
    assert.ok(car.components.length > 0);
    assert.equal(new Set(car.components.map(c => c.id)).size, car.components.length, "component ids unique");
    for (const c of car.components) {
      assert.match(c.subsystem, /^[a-z0-9-]+$/);
      assert.ok(exists(`subsystems/${c.subsystem}.js`), `subsystems/${c.subsystem}.js`);
      assert.ok(c.label && c.view?.pos?.length === 3 && c.view?.target?.length === 3, `${c.id}: label and view`);
      assert.ok(c.talk?.length > 0 && c.talk.every(t => t.length > 20), `${c.id}: talk points`);
    }
    assert.ok(Array.isArray(car.unverified) && Array.isArray(car.sources));
    for (const s of car.sources) assert.match(s.url, /^https:\/\//);
  });

  if (car.photo) test(`${car.slug}: photo, camera fit and credit`, () => {
    assert.ok(exists(`stops/${car.slug}/${car.photo.src}`), "photo file");
    assert.ok(car.photo.w > 0 && car.photo.h > 0 && car.photo.alt);
    assert.ok(["c", "yaw", "pitch", "roll", "f"].every(k => k in car.photo.cam));
    assert.ok(car.photo.credit?.author && car.photo.credit.license && car.photo.credit.url);
  });
}
// Shared test helpers: load the tour and every car config (pure data, no three.js).
import tour from "../../stops/tour.js";

export { tour };
export const loadCars = () => Promise.all(tour.map(async s => (await import(`../../stops/${s.slug}/car.js`)).default));
=== subsystems/aero.js
// A full-power run against the air: engine power against aerodynamic drag (½ρ·cd·A·v²: the power for it grows with v³)
// and rolling resistance. The chart plots power needed over speed for each body; where it meets the engine's power is the
// top speed. Wind streaks and two arrows (drag at the nose, drive at the wheels) show the forces during the run.
// Params (mm, ground at z = 0): label, shapes [{ id, label, cd, area (m²), mass (kg), crr, eta, ps, quoted? (km/h) }],
// power { min, max } (PS), vmax (km/h, chart), nose [x, z], wheel [x, z], wind { x0, x1, y, z0, z1 }, time (× real),
// ground? (z of the road, default 0, for cars whose origin is at axle height).
=== subsystems/air-suspension.js
// Self-levelling air suspension against steel springs. Load the car: on steel springs the body sinks, mostly at the
// rear, and stays down. On air springs it sinks too, then the levelling valves let more air into the bellows until the
// body is back at ride height; the higher pressure also stiffens the spring, so the ride frequency hardly changes.
// Params (mm, ground at z = 0): label, front (x of the front axle), wheelbase, halfTrack, wheelR,
// corners { front: { mass, extra }, rear: { mass, extra } } (kg sprung per corner; kg added per corner when loaded),
// air { area (m²), volume (m³), n }, steel { front, rear } (N/m), damping (N·s/m), bellows { r, h, z0 } (mm),
// load { heads: [[x, y, z]], boot: [x, z] } (mm, what is drawn when loaded).
=== subsystems/crumple-zone.js
// Frontal crash into a rigid wall, slowed right down. The front structure folds from the bumper back and soaks up the
// energy over a long distance at a moderate force; the passenger cell stays whole. Compare a stiff front: the car stops
// in a shorter distance, so the force (and the deceleration on the occupants) is far higher, and the cell is pushed in.
// Params (mm, ground at z = 0): label, mass (kg), speed { min, max, value } (km/h), slow (× slower than real),
// cases [{ id, label, zone, cellK }] (lib/model/crash.js; first = safety body), folds (number of fold rings),
// body { bumper, firewall, cellRear, tail, w (half width), sill, belt, roof }, wheels { front, rear, R }.
=== subsystems/desmo-valvetrain.js
// One-cylinder close-up: a desmodromic valve (opened by one cam, pulled shut by a conjugate cam through a rocker) next to a
// conventional spring-closed valve on an identical cam. Physics runs at the real engine speed (lib/model/valvetrain.js);
// the picture turns in slow motion. Params: cam { lift, open, duration, mass, preload, floatRpm, base } (m, cam rad, kg),
// rpm { min, max, value } (crank rpm), label, origin? [x, y, z] (m).
=== subsystems/differential.js
// Driven axle with an open differential: crown wheel (or belt pulley) and carrier, two spider gears on a cross pin, two
// side gears on the half-shafts. mode "corner": the outer wheel has further to go and the spider gears start to turn.
// mode "grip": one wheel on a slippery patch; open, it spins and the car stays put; locked, both wheels pull.
// Params (mm, ground at z = 0): label, mode, halfTrack, wheelR, axleX, wheel "wire" | "tyre", tyreW?, ringR,
// drive "crown" | "belt", counter? { x, z, half } (differential on a countershaft, chains to the wheels: Benz 1886),
// corner? { kmh, minRadius (m) }, grip? { torque (N·m at the axle), normal (N per wheel), muLow, muHigh, resist (N),
// surface (label), locks (bool) }.
=== subsystems/gearbox.js
// Sliding-gear gearbox without synchromesh, seen from the side: primary shaft (from the clutch) on top, secondary shaft
// below. Selecting a gear slides that pair into mesh, but the teeth only go in once both wheels run at about the same
// speed; until then they grind. Upshift: clutch down and wait for the primary shaft to slow. Downshift: double-declutch
// (clutch up in neutral, blip the throttle until the speeds match). A demo drive shifts 1 → 4 and coasts to a stop.
// Params (mm): label, box (lib/model/gearbox.js), module (gear radius per tooth ×2), pos [x, z] of the first pair,
// pitch (pair spacing, rearwards), width (gear face), rpm { idle, max }, gate [[name, col, row]],
// drive { accel (km/h per s at full throttle in a 1 : 1 gear), roll (km/h per s), drag (km/h per s per (km/h)²) }.
=== subsystems/inline-engine.js
// Inline piston engine turning over: crank, conrods, pistons, valves lifting in time, chambers coloured by stroke.
// Params (mm, deg): label, order (firing order), bore, stroke, rod, xs (cylinder x positions, cyl 1 first), crankZ, lean
// (+ = leans right), valvetrain "ohc" | "dohc" | "ohv" (pushrods) | "atmospheric", ignition "spark" | "hot-tube" |
// "compression" (diesel), fuel "carb" | "direct" | "prechamber" (diesel), compression? { value, min, max } (adds the
// compression-heat card),
// crankcase "open" | "flywheels", speed { min, max, value } (shown rpm, slow motion), realRpm? (readout note),
// valvetrain "none" (valve gear not drawn), flywheelR? (mm; with "flywheels" it also sizes the round case), rot? [x, y, z] (deg, turns the whole engine about the crank
// centre: [0, 90, 0] lays it flat with the cylinder pointing forward and the crank vertical).
=== subsystems/linkage-suspension.js
// Independent suspension from five fixed-length links (multi-link or double wishbone), driven over the road loop by the
// quarter-car model. One side is built and mirrored. Params (mm unless noted) — see stops/190e/car.js, stops/540k/car.js:
//   axle "front"|"rear", label, readouts [travel|load|camber|toe|track], W0, links [{ name, tok, b, c }], legendTitle, legend?,
//   frame [[a, b, r]], bracket { y, z?, r? }, carrier { style: "hub", disc } | { style: "knuckle", kingpin: [i, j], arm: k, drum },
//   wheel { type: "tyre"|"wire", R, r, spokeR?, y }, spring { link, at, from?, top? | topOffset?, turns, r, pad? },
//   drive? { diff, box, inner, outer }, road { x0, x1, seg } (m), patch [len, width] (m)
=== subsystems/radiator.js
// Engine cooling water and its radiator: the water warms in the engine, rises to the radiator, gives its heat to the air
// streaming through the core and comes back cooler. With too little radiator it reaches 100 °C and boils away: shown as
// litres lost per hour and per 100 km, the measure Daimler used. Time runs ×20 so a warm-up fits into a visit.
// Params (mm, ground at z = 0): label, heat (W into the water at full load), airT (°C), speed { min, max, value } (km/h),
// types [{ id, label, kind "tank" | "tubular" | "honeycomb", ua (W/K), still, refSpeed (km/h), water (kg), fan? }],
// engine { x, z, l, w, h } (block centre and size), radiator { x, z, w, h, d } (core centre and size).
=== subsystems/roots-blower.js
// Clutch-engaged Roots supercharger blowing through the carburettor into an inline engine (540 K, SSK).
// Params: blower (lib/model/blower.js params), order (firing order; its length = cylinder count), engineLabel,
// offset? [x, y, z] (m, group position in the car frame), spacing? (m, bore spacing).
=== subsystems/space-frame.js
// Tubular space frame under a twisting load: one front wheel is lifted, the rear is held, as when a car crosses a kerb at
// an angle. Tubes are coloured by force (tension, compression) and the bending is drawn hugely exaggerated. Compare the
// 300 SL frame, whose side trusses run deep through the door area (so the doors had to open upwards), with the same frame
// cut down to a low sill for ordinary doors.
// Params (mm, ground at z = 0): label, stations, bays (lib/model/truss.js; door: "high" marks the door bays), EA (N),
// load (N at the front-left corner), exaggerate (× displacement), modes { high, low } (button labels).
=== subsystems/steering.js
// Front steering seen from above: Benz's double-pivot (stub-axle) trapezoid against the older centre-pivot turntable axle,
// with each front wheel's axis drawn out to the rear-axle line (where they meet = the turning centre).
// Params (mm, deg): label, kingpinHalf, arm, wheelbase, frontR, rearR, halfTrackRear, stub (kingpin → wheel centre),
// maxSteer. Vehicle frame: rear axle at x = 0, front axle at x = wheelbase.
=== subsystems/wankel.js
// Wankel rotary engine: triangular rotors turning inside two-lobed housings on one eccentric shaft. Each rotor turns at a
// third of shaft speed while its centre circles on the eccentric, so its three tips stay on the housing; the three
// chambers between rotor and housing each run intake, compression, power and exhaust. The end view colours the
// chambers of rotor 1 by stroke.
// Params (mm): label, geometry { e, R, b, flank } (lib/model/wankel.js), compression (quoted ratio), rotors (count),
// spacing (along x), phases (deg of shaft per rotor), origin [x, y, z] (shaft centre of rotor 1), speed { min, max, value }
// (shown rpm, slow motion), realRpm.

// Page shell for every stop: stop.html?s=<slug>. Builds the page from stops/tour.js + stops/<slug>/car.js, loads each
// component's subsystem, and owns the Component/View switches, photo view, car outline, ghost body and frame loop.
import tour from "../../stops/tour.js";
import { createPanel } from "./panel.js";
import { registerOffline } from "./offline.js";

const params = new URLSearchParams(location.search);
const slug = params.get("s");
const idx = tour.findIndex(t => t.slug === slug);   // validated before any dynamic import
const app = document.getElementById("app");

function h(tag, attrs = {}, ...kids) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) if (v != null && v !== false) el.setAttribute(k, v === true ? "" : v);
  for (const k of kids.flat()) if (k != null) el.append(k);
  return el;
}
const link = (href, text) => h("a", { href, target: href.startsWith("http") ? "_blank" : null, rel: href.startsWith("http") ? "noopener" : null }, text);
const seg = (label, items, cur) => h("div", { class: "seg-group" }, h("span", { class: "seg-label" }, label),
  h("span", { class: "seg", role: "group", "aria-label": label }, items.map(([v, text]) => h("button", { type: "button", "data-v": v, "aria-pressed": String(v === cur) }, text))));

registerOffline();
if (idx < 0) {
  document.title = "Stop not found · Museum tour";
  app.replaceChildren(h("h1", {}, "Stop not found"), h("p", {}, "This QR code or link does not match a stop on the tour. ", link("./", "Open the tour route")));
} else {
  main().catch(err => {
    console.error(err);
    const stage = document.getElementById("stage");
    (stage ?? app).append(h("p", { class: "fail" }, "The 3D view could not load. Check your connection and reload the page; after one visit with signal it also works offline."));
  });
}

async function main() {
  const stop = tour[idx];
  const car = (await import(`../../stops/${stop.slug}/car.js`)).default;
  const base = `stops/${stop.slug}/`;
  document.title = `${car.name} · Museum tour`;
  const state = { comp: car.components[0].id, view: "model", outline: false };
  const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;

  // ---------- page ----------
  const prev = tour[idx - 1], next = tour[idx + 1];
  const nameOf = async s => (s ? (await import(`../../stops/${s.slug}/car.js`)).default.name : null);
  const [prevName, nextName] = await Promise.all([nameOf(prev), nameOf(next)]);
  const photo = car.photo;
  const img = photo ? h("img", { src: base + photo.src, alt: photo.alt, width: photo.w, height: photo.h, hidden: true }) : null;
  const credit = photo ? h("div", { class: "credit", hidden: true }, "Photo: ", link(photo.credit.url, photo.credit.author), `, ${photo.credit.license}`) : null;
  const hint = h("div", { class: "hint" }, "drag to orbit · pinch to zoom");
  const stageEl = h("div", { class: "stage", id: "stage", style: photo ? `--aspect:${photo.w}/${photo.h};--ar:${(photo.w / photo.h).toFixed(4)}` : null }, img, hint, credit);
  const side = h("div", { class: "side" });
  const outlineBtn = h("button", { type: "button", class: "outline", "aria-pressed": "false", "data-only": "photo" }, "Car outline");
  const toolbar = h("div", { class: "toolbar" },
    car.components.length > 1 ? seg("Component", car.components.map(c => [c.id, c.label]), state.comp) : null,
    photo ? seg("View", [["model", "3D model"], ["photo", "Museum photo"]], state.view) : null,
    photo ? outlineBtn : null);
  app.replaceChildren(
    h("nav", { class: "crumbs" }, link("./", "← Tour route"), h("span", {}, `Stop ${idx + 1} of ${tour.length} · ${stop.room} · Level ${stop.level}`)),
    h("header", {}, h("div", { class: "eyebrow" }, car.eyebrow), h("h1", {}, car.title), h("p", { class: "lede" }, car.lede)),
    toolbar,
    h("section", { class: "viewer", "aria-label": "Interactive component viewer" }, stageEl, side),
    h("nav", { class: "pager", "aria-label": "Previous and next stop" },
      prev ? link(`stop.html?s=${prev.slug}`, `← ${prevName}`) : h("span"), next ? link(`stop.html?s=${next.slug}`, `${nextName} →`) : h("span")),
    h("footer", {},
      car.unverified?.length ? h("details", {}, h("summary", {}, "Illustrative, not verified"), h("ul", {}, car.unverified.map(u => h("li", {}, u)))) : null,
      car.sources?.length ? h("details", {}, h("summary", {}, "Sources"), h("ul", {}, car.sources.map(s => h("li", {}, link(s.url, s.label))))) : null,
      h("p", { class: "note" }, "Unofficial private tour notes, not affiliated with Mercedes-Benz. 3D: three.js (MIT). Mechanisms are original code from illustrative hardpoints.")));

  // ---------- 3D ----------
  const [{ createStage }, { buildGhost }] = await Promise.all([import("../scene/stage.js"), import("../scene/ghost-body.js")]);
  const stage = createStage(stageEl, car);
  const carRoot = new stage.THREE.Group(); stage.scene.add(carRoot);
  const ghost = buildGhost(car.body?.ghost); carRoot.add(ghost.group);
  stage.onTheme(({ onPhoto }) => { const c = onPhoto ? new stage.THREE.Color(0xffffff) : stage.color("--fg"); ghost.fill.color.copy(c); ghost.edge.color.copy(c); });

  const instances = new Map();
  for (const comp of car.components) {
    if (!/^[a-z0-9-]+$/.test(comp.subsystem)) throw new Error(`bad subsystem id ${comp.subsystem}`);
    const mod = await import(`../../subsystems/${comp.subsystem}.js`);
    const panel = createPanel(side, comp.id);
    const inst = mod.create({ stage, carRoot, frame: car.frame, ride: car.ride, panel, reducedMotion }, comp.params);
    panel([{ label: "What to say at the car", items: [{ list: comp.talk }] }]);
    instances.set(comp.id, inst);
  }
  if (car.note) side.append(h("p", { class: "note" }, car.note));

  function layout(resetOrbit = true) {
    const onPhoto = state.view === "photo", comp = car.components.find(c => c.id === state.comp);
    document.querySelectorAll("[data-comp]").forEach(el => (el.hidden = el.dataset.comp !== state.comp));
    document.querySelectorAll("[data-only]").forEach(el => { if (!el.closest("[data-comp]")?.hidden) el.hidden = (el.dataset.only === "photo") !== onPhoto; });
    if (img) { img.hidden = !onPhoto; credit.hidden = !onPhoto; }
    hint.hidden = onPhoto;
    outlineBtn.setAttribute("aria-pressed", String(state.outline));
    ghost.group.visible = onPhoto ? state.outline : (comp.ghost?.fill ?? 0) + (comp.ghost?.edge ?? 0) > 0;
    ghost.fill.opacity = onPhoto ? 0 : comp.ghost?.fill ?? 0.06;
    ghost.edge.opacity = onPhoto ? 0.7 : comp.ghost?.edge ?? 0.5;
    for (const [id, inst] of instances) inst.layout?.({ active: id === state.comp, onPhoto });
    stage.setPhotoView(onPhoto);
    if (!onPhoto && resetOrbit) stage.setOrbit(comp.view);
  }
  toolbar.addEventListener("click", e => {
    const b = e.target.closest("button"); if (!b) return;
    if (b === outlineBtn) { state.outline = !state.outline; return layout(false); }
    const group = b.closest(".seg-group"), key = group.querySelector(".seg-label").textContent === "View" ? "view" : "comp";
    state[key] = b.dataset.v;
    group.querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", String(x === b)));
    layout();
  });

  layout();
  stage.start(dt => {
    carRoot.position.set(0, 0, 0); carRoot.rotation.set(0, 0, 0);
    instances.get(state.comp).update(dt, { onPhoto: state.view === "photo" });
  });
  if (params.has("debug")) window.__tour = { state, stats: stage.stats, info: () => stage.renderer.info.render, ready: true };
}
// Translucent "ghost" body built from data in car.body.ghost (mm, vehicle frame). Parts:
//   { pts: [[x, z] | { arc: [cx, cz, r, a0°, a1°, n] }, …], y: [y0, y1], mirror? }   side profile extruded across y
//   { torus: { R, r, pos: [x, y, z], rot: [rx°, ry°, rz°] } }                        e.g. a spare wheel
//   { cyl: { r: [rTop, rBottom], h, axis: "x" | "y" | "z", pos: [x, y, z] }, mirror? } e.g. a headlamp
// mirror: also build the part reflected to −y. A later GLB body can replace this module behind the same return shape.
import * as THREE from "three";
import { profileExtrude, edgesOf } from "./helpers.js";

const D = Math.PI / 180;

export function buildGhost(parts = []) {
  const group = new THREE.Group();
  const fill = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.06, depthWrite: false, side: THREE.DoubleSide });
  const edge = new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.5 });
  for (const part of parts) {
    for (const s of part.mirror ? [1, -1] : [1]) {
      let geo;
      if (part.pts) {
        const [y0, y1] = part.y;
        geo = s > 0 ? profileExtrude(part.pts, y0, y1) : profileExtrude(part.pts, -y1, -y0);
      } else if (part.torus) {
        const t = part.torus;
        geo = new THREE.TorusGeometry(t.R / 1000, t.r / 1000, 8, 32);
        const e = new THREE.Euler(...(t.rot ?? [0, 0, 0]).map(a => a * D));
        geo.applyMatrix4(new THREE.Matrix4().makeRotationFromEuler(e)).translate(t.pos[0] / 1000, s * t.pos[1] / 1000, t.pos[2] / 1000);
      } else if (part.cyl) {
        const c = part.cyl;
        geo = new THREE.CylinderGeometry(c.r[0] / 1000, c.r[1] / 1000, c.h / 1000, 20);
        if (c.axis === "x") geo.rotateZ(Math.PI / 2); else if (c.axis === "z") geo.rotateX(Math.PI / 2);
        geo.translate(c.pos[0] / 1000, s * c.pos[1] / 1000, c.pos[2] / 1000);
      }
      if (geo) edgesOf(geo, group, fill, edge, 25);
    }
  }
  return { group, fill, edge };
}
// Declarative side-panel cards. A subsystem describes its cards; this builds the DOM (textContent only) and returns handles.
// Card: { label, badge?: { id, text }, only?: "model" | "photo", items: [widget] }. Widgets (one key each, plus optional `only`):
//   readouts: [{ id, label, unit, value }]          → ui.set(id, text)
//   trace: { id, series: [{ token, min, max }], span, top, bottom, aria }   → ui.trace(id).push(t, [v…]) / .draw(t)
//   buttons: [{ id, label, toggle?: [onLabel, offLabel], pressed?, onClick(pressed) }]   → ui.toggle(id).set(bool)
//   slider: { id, label, min, max, step, value, onInput(v) }   → ui.slider(id).set(v)
//   meter: { id }  → ui.meter(id).set(0..1, hot)        cells: { id, labels }  → ui.cells(id).set(i, text, on)
//   legend: [[token, name]]   key: [[token, text]]   svg: { id, viewBox, aria }  → ui.el(id)   text: "…"   list: ["…"]
const SVG = "http://www.w3.org/2000/svg";

function h(tag, attrs = {}, ...kids) {
  const el = tag.startsWith("svg:") ? document.createElementNS(SVG, tag.slice(4)) : document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) if (v != null && v !== false) el.setAttribute(k, v === true ? "" : v);
  for (const k of kids.flat()) if (k != null) el.append(k);
  return el;
}

export function createPanel(container, compId) {
  const els = new Map(), api = {};
  const key = id => `${compId}-${id}`;

  const widgets = {
    readouts: items => h("div", { class: "readouts" }, items.map(r => {
      const o = h("output", { id: key(r.id) }, r.value ?? "–"); els.set(r.id, o);
      return h("div", {}, h("small", {}, r.label), o, h("small", {}, r.unit ?? ""));
    })),
    trace: t => {
      const svg = h("svg:svg", { viewBox: "0 0 280 110", role: "img", "aria-label": t.aria ?? "" });
      const grid = [[55, null], [5, "2 3"], [105, "2 3"]].map(([y, dash]) => h("svg:line", { x1: 0, y1: y, x2: 280, y2: y, stroke: "var(--rule)", "stroke-dasharray": dash }));
      const lines = t.series.map(s => h("svg:polyline", { fill: "none", stroke: `var(${s.token})`, "stroke-width": 1.6 }));
      svg.append(...grid, ...lines, h("svg:text", { x: 278, y: 15, "text-anchor": "end" }, t.top ?? ""), h("svg:text", { x: 278, y: 101, "text-anchor": "end" }, t.bottom ?? ""));
      const buf = [], span = t.span ?? 6;
      els.set(t.id, {
        push(time, values) { buf.push({ time, values }); },
        draw(now) {
          while (buf.length && buf[0].time < now - span) buf.shift();
          const X = tt => ((tt - (now - span)) / span * 280).toFixed(1);
          t.series.forEach((s, i) => lines[i].setAttribute("points", buf.map(p => {
            const v = Math.max(s.min, Math.min(s.max, p.values[i]));
            return `${X(p.time)},${(105 - (v - s.min) / (s.max - s.min) * 100).toFixed(1)}`;
          }).join(" ")));
        },
      });
      return h("div", { class: "trace" }, svg);
    },
    buttons: items => h("div", { class: "row" }, items.map(b => {
