    engine.setAttribute("y1", Yk(kw).toFixed(1)); engine.setAttribute("y2", Yk(kw).toFixed(1));
    topDot.setAttribute("cx", X(top).toFixed(1)); topDot.setAttribute("cy", Yk(kw).toFixed(1));
