    knob = [knob[0] + (tx - knob[0]) * 0.3, knob[1] + (ty - knob[1]) * 0.3];
    knobEl.setAttribute("cx", gx(knob[0]).toFixed(1)); knobEl.setAttribute("cy", gy(knob[1]).toFixed(1));
    ui.set("kmh", Math.abs(kmh).toFixed(1) + (kmh < -0.05 ? " back" : "")); ui.set("eng", eng.toFixed(0)); ui.set("prim", prim.toFixed(0));
    ui.set("need", want === null ? "–" : Math.abs(primaryRpmFor(box, want, kmh)).toFixed(0));
    ui.badge("mesh").set(sel !== null ? `In gear ${nameOf(sel)}` : grinding ? `Grinding: ${(mismatch(box, want, prim, kmh) * 100).toFixed(0)} % apart` : "Neutral", sel !== null);
  }

  return {
    layout({ active }) { group.visible = active; },
    update(dt) {
      if (demo) { age += dt; if (age === dt) script[step].go(); if (script[step].done()) { step = (step + 1) % script.length; age = 0; script[step].go(); } }
      for (let i = 0; i < 4; i++) physics(dt / 4);
      show(dt);
    },
  };
}
// Differential, gearbox and road-load (aero) models.
import { test } from "node:test";
import assert from "node:assert/strict";
import { cornerSpeeds, traction } from "../../lib/model/differential.js";
import { ratio, roadSpeed, primaryRpmFor, mismatch } from "../../lib/model/gearbox.js";
import { drag, powerNeeded, topSpeed, accelerate } from "../../lib/model/aero.js";
import { loadCars } from "./helpers.mjs";

const axle = { halfTrack: 0.7, wheelR: 0.36 };

test("differential: equal wheel speeds straight ahead; the outer wheel turns faster in a corner", () => {
  const s = cornerSpeeds(axle, Infinity, 10);
  assert.equal(s.left, s.right); assert.equal(s.diff, 0);
  const l = cornerSpeeds(axle, 7, 10);   // left turn, 7 m radius
  assert.ok(l.right > l.left);
  assert.ok(Math.abs(l.carrier - 10 / axle.wheelR) < 1e-12, "carrier turns at the mean");
  assert.ok(Math.abs(l.right / l.left - (7 + 0.7) / (7 - 0.7)) < 1e-12);
  const r = cornerSpeeds(axle, -7, 10);
  assert.ok(Math.abs(r.left - l.right) < 1e-12, "mirror image for a right turn");
});

test("differential: open splits torque equally, so one wheel on ice stops the car; a lock gets it moving", () => {
  const p = { torque: 3000, wheelR: 0.36, normal: 5000, muL: 0.08, muR: 0.7, resist: 1500 };
  const open = traction({ ...p, locked: false }), locked = traction({ ...p, locked: true });
  assert.ok(Math.abs(open.fL - 0.08 * 5000) < 1e-9 && open.fL === open.fR);
  assert.ok(open.spinL && !open.spinR && !open.moves);
  assert.ok(Math.abs(locked.total - Math.min(3000 / 0.36, 0.78 * 5000)) < 1e-9);
  assert.ok(locked.moves && locked.fR > locked.fL);
  const dry = traction({ ...p, torque: 2000, muL: 0.7, locked: false });
  assert.ok(dry.moves && !dry.spinL && !dry.spinR && Math.abs(dry.total - 2000 / 0.36) < 1e-9);
  const both = traction({ ...p, muL: 0.7, locked: false });
  assert.ok(both.spinL && both.spinR, "equal grip, too much torque: both spin");
});

const box = { gears: [{ name: "R", drive: 15, driven: 45, idler: true }, { name: "1", drive: 15, driven: 45 }, { name: "2", drive: 20, driven: 40 }, { name: "4", drive: 30, driven: 30 }], final: 2, wheelR: 0.45 };

test("gearbox: ratios, reverse runs backwards, primary speed and road speed are inverse", () => {
  assert.equal(ratio(box, 1), 3); assert.equal(ratio(box, 3), 1); assert.equal(ratio(box, 0), -3);
  assert.equal(ratio(box, null), Infinity); assert.equal(roadSpeed(box, null, 1000), 0);
  assert.ok(roadSpeed(box, 0, 1000) < 0);
  assert.ok(roadSpeed(box, 1, 1000) < roadSpeed(box, 2, 1000) && roadSpeed(box, 2, 1000) < roadSpeed(box, 3, 1000));

  assert.ok(roadSpeed(box, 0, 1000) < 0);
  assert.ok(roadSpeed(box, 1, 1000) < roadSpeed(box, 2, 1000) && roadSpeed(box, 2, 1000) < roadSpeed(box, 3, 1000));
  for (const g of [0, 1, 2, 3]) assert.ok(Math.abs(primaryRpmFor(box, g, roadSpeed(box, g, 900)) - 900) < 1e-9);
});

test("gearbox: a pair only meshes cleanly when its speeds match", () => {
  const kmh = roadSpeed(box, 1, 1000);
  assert.ok(mismatch(box, 1, 1000, kmh) < 1e-12);
  assert.ok(mismatch(box, 2, 1000, kmh) > 0.3, "upshift without letting the primary shaft slow down");
  assert.ok(mismatch(box, 2, primaryRpmFor(box, 2, kmh), kmh) < 1e-12);
  assert.equal(mismatch(box, 1, 0, 0), 0, "standing still with the clutch out");
});

const car = { cd: 0.36, area: 2.3, mass: 2500, crr: 0.02, eta: 0.7 };

test("aero: top speed is where power needed meets power available; drag grows with v²", () => {
  const v = topSpeed(car, 132e3);
  assert.ok(Math.abs(powerNeeded(car, v) - 132e3) < 1);
  assert.ok(Math.abs(drag(car, 2 * v) / drag(car, v) - 4) < 1e-12);
  assert.ok(topSpeed({ ...car, cd: 0.48 }, 132e3) < v, "more drag, lower top speed");
  const v2 = topSpeed(car, 2 * 132e3);
  // Drag power grows with v³, so doubling the power buys only about ∛2 ≈ 1.26× the speed (a little more, because
  // rolling resistance grows only with v).
  assert.ok(v2 / v > Math.cbrt(2) && v2 / v < 1.35);
});

test("aero: a full-power run approaches the top speed and never passes it", () => {
  const P = 132e3, vt = topSpeed(car, P);
  let v = 0;
  for (let t = 0; t < 400; t += 0.02) { v = accelerate(car, P, v, 0.02); assert.ok(v <= vt + 1e-6); }
  assert.ok(v > 0.99 * vt);
});

test("every aero config's model top speed is within 5 % of the quoted one", async () => {
  for (const c of await loadCars()) for (const comp of c.components.filter(k => k.subsystem === "aero"))
    for (const s of comp.params.shapes) if (s.quoted) {
      const kmh = topSpeed(s, s.ps * 735.5) * 3.6;
      assert.ok(Math.abs(kmh / s.quoted - 1) < 0.05, `${c.slug} ${s.id}: model ${kmh.toFixed(0)} vs ${s.quoted} km/h`);
    }
});
// Wankel geometry, radiator cooling and diesel compression.
import { test } from "node:test";
import assert from "node:assert/strict";
import { housing, rotorCentre, apexes, displacement, chamberVolume, flank, strokeOf, compressionRatio, STROKES } from "../../lib/model/wankel.js";
import { uaAt, steadyTemp, boilRate, perHundredKm, createCooling } from "../../lib/model/cooling.js";
import { compressionTemp, injectingDiesel } from "../../lib/model/engine.js";
import { loadCars } from "./helpers.mjs";

const D = Math.PI / 180;
const m950 = { e: 0.015, R: 0.099, b: 0.075, flank: 0.0169 };   // Wikipedia's M 950 F figures; flank illustrative

test("wankel: apexes stay on the housing at radius R from the rotor centre", () => {
  for (let d = 0; d < 1080; d += 7) {
    const th = d * D, c = rotorCentre(th, m950);
    for (const p of apexes(th, m950)) assert.ok(Math.abs(Math.hypot(p[0] - c[0], p[1] - c[1]) - m950.R) < 1e-12);
  }
  assert.ok(Math.abs(housing(0, m950)[0] - (m950.R + m950.e)) < 1e-15);
});

test("wankel: swept volume matches 3√3·e·R·b; the flank fits inside the housing at every angle", () => {
  const cr = compressionRatio(m950);
  assert.ok(Math.abs((cr.vmax - cr.vmin) / displacement(m950) - 1) < 0.01);
  const H = Array.from({ length: 720 }, (_, i) => housing(i / 720 * 2 * Math.PI, m950));
  const inside = ([x, y]) => { let c = false; for (let i = 0, j = H.length - 1; i < H.length; j = i++) { const [xi, yi] = H[i], [xj, yj] = H[j]; if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) c = !c; } return c; };
  for (let d = 0; d < 360; d += 6) for (let k = 0; k < 3; k++) for (const p of flank(d * D, k, m950).slice(1, -1)) assert.ok(inside(p), `flank leaves the housing at ${d}°`);
});

test("wankel: each chamber runs intake → compression → power → exhaust, 270° of shaft each, volume peaking between", () => {
  const seen = [];
  for (let d = 91; d < 1171; d += 2) { const s = strokeOf(d * D, 0).stroke; if (seen.at(-1) !== s) seen.push(s); }
  assert.deepEqual(seen, STROKES);
  for (let k = 0; k < 3; k++) {
    const ths = [90, 360, 630, 900].map(d => d * D - k * 2 * Math.PI);   // chamber k runs 360° of shaft ahead of chamber k − 1
    assert.equal(strokeOf(ths[0] + 0.01, k).stroke, "Intake");
    assert.ok(chamberVolume(ths[1], k, m950) > chamberVolume(ths[0], k, m950), "largest at the end of intake");
  }
  assert.ok(Math.abs(compressionRatio(m950).ratio - 9.3) < 0.3);
});

test("every wankel config fits its compression ratio and the flank stays inside the housing", async () => {
  for (const c of await loadCars()) for (const comp of c.components.filter(k => k.subsystem === "wankel")) {
    const g = Object.fromEntries(Object.entries(comp.params.geometry).map(([k, v]) => [k, v / 1000]));
    assert.ok(Math.abs(compressionRatio(g).ratio - comp.params.compression) < 0.3, c.slug);
  }
});

const tubular = { water: 20, ua: 70, refSpeed: 30 / 3.6, still: 0.15, airT: 20 };
const honeycomb = { water: 20, ua: 445, refSpeed: 60 / 3.6, still: 0.3, airT: 20 };

test("cooling: the radiator sheds more with airflow; calibrated to the halved water use of 1898 → 1900", () => {
  assert.ok(uaAt(tubular, 0) === 0.15 * 70 && uaAt(tubular, 30 / 3.6) === 70);
  assert.ok(Math.abs(steadyTemp(tubular, 3500, 30 / 3.6) - 70) < 1e-9);
  assert.equal(boilRate(tubular, 3500, 30 / 3.6), 0);
  // Phoenix 8 hp (≈ 9 kW to the water) at 30 km/h: 18 l/100 km; Mercedes 35 PS (≈ 39 kW) at 60 km/h: 9 l/100 km.
  assert.ok(Math.abs(perHundredKm(boilRate(tubular, 9000, 30 / 3.6), 30) - 18) < 0.5);
  assert.ok(Math.abs(perHundredKm(boilRate(honeycomb, 39000, 60 / 3.6), 60) - 9) < 0.5);
  assert.equal(perHundredKm(0.001, 0), Infinity);
});

test("cooling: water warms towards the steady temperature, never passes 100 °C, and then boils away", () => {
  const s = createCooling(tubular);
  let T = s.T;
  for (let i = 0; i < 3000; i++) { s.step(9000, 30 / 3.6, 1); assert.ok(s.T >= T - 1e-9 && s.T <= 100); T = s.T; }
  assert.equal(s.T, 100); assert.ok(s.boiling && s.boiled > 0);
  s.reset(); assert.equal(s.T, 20); assert.equal(s.boiled, 0);
});

test("diesel: compression alone heats the air well past diesel's self-ignition; petrol ratios do not", () => {
  assert.ok(compressionTemp(20.5) > 400 && compressionTemp(6) < 250, "≈ 450 °C at 20.5:1, ≈ 230 °C at 6:1");
  assert.ok(Math.abs(compressionTemp(1) - 20) < 1e-9);
  assert.ok(injectingDiesel(4 * Math.PI - 0.1) && injectingDiesel(0.05) && !injectingDiesel(Math.PI));
});

// Driven axle with an open differential: crown wheel (or belt pulley) and carrier, two spider gears on a cross pin, two
// side gears on the half-shafts. mode "corner": the outer wheel has further to go and the spider gears start to turn.
// mode "grip": one wheel on a slippery patch; open, it spins and the car stays put; locked, both wheels pull.
// Params (mm, ground at z = 0): label, mode, halfTrack, wheelR, axleX, wheel "wire" | "tyre", tyreW?, ringR,
// drive "crown" | "belt", counter? { x, z, half } (differential on a countershaft, chains to the wheels: Benz 1886),
// corner? { kmh, minRadius (m) }, grip? { torque (N·m at the axle), normal (N per wheel), muLow, muHigh, resist (N),
// surface (label), locks (bool) }.
import * as THREE from "three";
import { V, mat, rod, place, tyre, wireWheel, line } from "../lib/scene/helpers.js";
import { cornerSpeeds, traction } from "../lib/model/differential.js";

const SLOW = 0.3, SIDE = 0.05, PIN = 0.045, Z_SIDE = 16, Z_SPIDER = 10;   // shown speed share; gear offsets (m); teeth

export function create(ctx, p) {
  const { stage, carRoot } = ctx, m = v => v / 1000;
  const h = m(p.halfTrack), R = m(p.wheelR), ax = m(p.axleX);
  const group = new THREE.Group(); carRoot.add(group);
  const iron = mat(0x5a626b, { metalness: 0.5 }), tyreMat = mat(0x2a2d31, { roughness: 0.9 }), dark = mat(0x343b42);
  const rimMat = mat(0x5a626b, { metalness: 0.5 }), wheelMats = [tyreMat, rimMat];   // faded over the museum photo
  const sideMat = stage.tokenMat("--l1"), spiderMat = stage.tokenMat("--l2"), carrierMat = stage.tokenMat("--metal"), shaftMat = stage.tokenMat("--l4");
  const K = p.counter ? 0.22 / 0.07 : 1;   // half-shaft turns per wheel turn (chain sprockets on the countershaft)
  const cx = p.counter ? m(p.counter.x) : ax, cz = p.counter ? m(p.counter.z) : R, half = p.counter ? m(p.counter.half) : h;
  const C = V(cx, 0, cz);
  const marked = (geo, material, markSize) => {   // a part with a dark mark so its rotation is visible
    const g = new THREE.Group(); g.add(new THREE.Mesh(geo, material));
    const k = new THREE.Mesh(new THREE.BoxGeometry(markSize[0], markSize[1], markSize[2]), dark); k.position.z = markSize[3] ?? 0; g.add(k); return g;
  };
  const spinner = (pos, part) => { const g = new THREE.Group(); g.position.copy(pos); g.add(part); group.add(g); return g; };

  // Wheels (axis along y) on their own spinners.
  const wheels = [1, -1].map(s => {
    const g = new THREE.Group();
    if (p.wheel === "wire") { const spokes = line(0x9aa4ad, 0.85); spokes.userData.solid = rimMat; wheelMats.push(spokes); g.add(wireWheel(tyreMat, spokes, R - 0.02, 0.02, R - 0.05, 28)); }
    else { const tw = m(p.tyreW ?? 110); g.add(tyre(tyreMat, R - tw, tw)); g.add(new THREE.Mesh(new THREE.CylinderGeometry(R - 1.8 * tw, R - 1.8 * tw, 0.14, 32), rimMat)); }
    const mk = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.15, 0.45 * R), carrierMat); mk.position.z = 0.4 * R; g.add(mk);
    return spinner(V(ax, s * h, R), g);
  });

  for (const w of wheelMats) { w.transparent = true; w.userData.opacity = w.opacity; }

  // Carrier: crown wheel or belt pulley, cross pin, two spider gears. Side gears turn with their half-shafts.
  const carrier = spinner(C, new THREE.Group());
  const ringR = m(p.ringR);
  if (p.drive === "belt") carrier.add(marked(new THREE.CylinderGeometry(ringR, ringR, 0.1, 40, 1, true), new THREE.MeshStandardMaterial({ color: 0x8a6a4a, transparent: true, opacity: 0.35, side: THREE.DoubleSide, depthWrite: false }), [0.03, 0.1, 0.03, ringR]));
  else { const crown = marked(new THREE.CylinderGeometry(ringR, ringR, 0.02, 40), carrierMat, [0.03, 0.022, 0.03, ringR - 0.02]); crown.position.y = -SIDE - 0.02; carrier.add(crown); }
  carrier.add(place(rod(carrierMat, 0.008), V(0, 0, -PIN - 0.02), V(0, 0, PIN + 0.02)));
  const spiders = [1, -1].map(s => {
    const holder = new THREE.Group(); holder.position.z = s * PIN; carrier.add(holder);
    const gear = marked(new THREE.CylinderGeometry(0.018, 0.03, 0.025, 20), spiderMat, [0.012, 0.03, 0.012, 0]);
    gear.children[1].position.set(0.022, 0, 0);
    gear.rotation.x = s > 0 ? -Math.PI / 2 : Math.PI / 2; holder.add(gear); return holder;
  });
  const sides = [1, -1].map(s => {
    const gear = marked(new THREE.CylinderGeometry(s > 0 ? 0.042 : 0.028, s > 0 ? 0.028 : 0.042, 0.03, 24), sideMat, [0.012, 0.032, 0.012, 0.03]);
    return spinner(V(cx, s * SIDE, cz), gear);
  });

  // Half-shafts; with a countershaft, sprockets and a chain to each wheel.
  const chainLinks = [];
  for (const s of [1, -1]) {
    group.add(place(rod(shaftMat, 0.014), V(cx, s * SIDE, cz), V(cx, s * half, cz)));
    if (!p.counter) continue;
    const yw = s * (h - 0.09), r1 = 0.07, r2 = 0.22;
    chainLinks.push(spinner(V(cx, s * half, cz), marked(new THREE.CylinderGeometry(r1, r1, 0.02, 24), iron, [0.02, 0.022, 0.02, r1 - 0.01])));
    chainLinks.push(spinner(V(ax, yw, R), marked(new THREE.CylinderGeometry(r2, r2, 0.02, 40), iron, [0.03, 0.022, 0.03, r2 - 0.02])));
    for (const t of [1, -1]) group.add(place(rod(dark, 0.006), V(cx, s * half, cz + t * r1), V(ax, yw, R + t * r2)));
  }
  const housing = new THREE.Mesh(new THREE.SphereGeometry(0.11, 24, 16), new THREE.MeshStandardMaterial({ color: 0x8fa3b3, transparent: true, opacity: 0.12, depthWrite: false }));
  housing.position.copy(C); if (p.drive !== "belt") group.add(housing);

  // Ground: wheel paths in a corner, slippery patch for the grip demo.
  const pathOf = token => { const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(Array.from({ length: 41 }, () => V(0, 0, 0))), new THREE.LineBasicMaterial()); stage.bind(l.material.color, token); l.frustumCulled = false; group.add(l); return l; };
  const paths = p.mode === "corner" ? [pathOf("--l1"), pathOf("--l2")] : [];
  const patch = new THREE.Mesh(new THREE.PlaneGeometry(1.2, 0.6), new THREE.MeshBasicMaterial({ transparent: true, opacity: 0.55, depthWrite: false }));
  stage.bind(patch.material.color, "--l4"); patch.position.set(ax, h, 0.004); patch.visible = p.mode === "grip"; group.add(patch);

  // ---------- state + panel ----------
  const D = 180 / Math.PI;
  let auto = !ctx.reducedMotion, t = 0, curve = 0.6, locked = false, angL = 0, angR = 0, angC = 0;   // half-shaft and carrier angles
  const ui = p.mode === "corner" ? ctx.panel([{ label: p.label, items: [
    { slider: { id: "curve", label: "Steering: right ← straight → left", min: -1, max: 1, step: 0.05, value: curve, onInput: v => { auto = false; ui.toggle("auto").set(false); curve = v; } } },
    { readouts: [{ id: "radius", label: "Turn radius", unit: "m, axle centre" }, { id: "left", label: "Left wheel", unit: "rpm" }, { id: "right", label: "Right wheel", unit: "rpm" },
      { id: "spider", label: "Spider gears", unit: "rpm in the carrier" }, { id: "extra", label: "Outer wheel goes", unit: "% further" }] },
    { buttons: [{ id: "auto", toggle: ["Auto demo on", "Auto demo off"], pressed: auto, onClick: v => (auto = v) }] },
    { key: [["--l1", "left wheel path"], ["--l2", "right wheel path"]] },
  ] }, { label: "Parts", items: [{ legend: [["--l1", "Side gears (one per half-shaft)"], ["--l2", "Spider gears"], ["--metal", p.drive === "belt" ? "Carrier inside the belt pulley" : "Carrier and crown wheel"], ["--l4", "Half-shafts"]] }] }])
    : ctx.panel([{ label: p.label, badge: { id: "moves", text: "" }, items: [
      { buttons: [{ id: "open", label: "Open differential", pressed: true, onClick: () => setLock(false) },
        ...(p.grip.locks ? [{ id: "lock", label: "Differential lock", pressed: false, onClick: () => setLock(true) }] : [])] },
      { readouts: [{ id: "fL", label: `Left wheel, on ${p.grip.surface}`, unit: "N of push" }, { id: "fR", label: "Right wheel, dry", unit: "N of push" },
        { id: "total", label: "Total drive", unit: `N, needs ${p.grip.resist} to move` }, { id: "spin", label: "Left wheel", unit: "rpm" }] },
      { buttons: [{ id: "auto", toggle: ["Auto demo on", "Auto demo off"], pressed: auto, onClick: v => (auto = v) }] },
      { key: [["--l4", `${p.grip.surface} under the left wheel`]] },
    ] }, { label: "Parts", items: [{ legend: [["--l1", "Side gears (one per half-shaft)"], ["--l2", "Spider gears"], ["--metal", "Carrier and crown wheel"], ["--l4", "Half-shafts"]] }] }]);
  function setLock(v) { locked = v; ui.toggle("open").set(!v); if (p.grip.locks) ui.toggle("lock").set(v); }

  const rpm = w => (w * 60 / (2 * Math.PI)).toFixed(0);
  function corner(dt) {
    if (auto) { t += dt; curve = Math.sin(0.35 * t); ui.slider("curve").set(curve.toFixed(2)); }
    const radius = Math.abs(curve) < 0.02 ? Infinity : p.corner.minRadius / curve, v = p.corner.kmh / 3.6;
    const s = cornerSpeeds({ halfTrack: h, wheelR: R }, radius, v);
    angL += s.left * K * SLOW * dt; angR += s.right * K * SLOW * dt; angC += s.carrier * K * SLOW * dt;
    const straight = !Number.isFinite(radius);
    [h, -h].forEach((y, i) => {   // each wheel's path, 4 m ahead
      const pos = paths[i].geometry.attributes.position;
      for (let k = 0; k <= 40; k++) {
        const d = k / 40 * 4;
        if (straight) pos.setXYZ(k, ax + d, y, 0.01);
        else { const rr = radius - y, a = d / Math.abs(rr); pos.setXYZ(k, ax + rr * Math.sin(a) * Math.sign(rr), radius - rr * Math.cos(a), 0.01); }
      }
      pos.needsUpdate = true;
    });
    ui.set("radius", straight ? "straight" : Math.abs(radius).toFixed(1));
    ui.set("left", rpm(s.left)); ui.set("right", rpm(s.right));
    ui.set("spider", rpm(Math.abs(s.diff) * Z_SIDE / Z_SPIDER));
    ui.set("extra", straight ? "0" : ((Math.max(s.left, s.right) / Math.min(s.left, s.right) - 1) * 100).toFixed(0));
  }
  function grip(dt) {
    if (auto) { t += dt; const lk = p.grip.locks && Math.floor(t / 5) % 2 === 1; if (lk !== locked) setLock(lk); }
    const g = p.grip, r = traction({ torque: g.torque, wheelR: R, normal: g.normal, muL: g.muLow, muR: g.muHigh, locked, resist: g.resist });
    const wC = 1.2 / R;   // carrier speed from the engine: walking pace, as on a slippery start
    // Open with the left wheel slipping: the right wheel stands and the left one turns twice as fast as the carrier.
    const [wL, wR] = locked ? [wC, wC] : r.spinL ? [2 * wC, 0] : r.moves ? [wC, wC] : [0, 0];
    angL += wL * K * SLOW * dt; angR += wR * K * SLOW * dt; angC += (wL + wR) / 2 * K * SLOW * dt;
    ui.set("fL", r.fL.toFixed(0)); ui.set("fR", r.fR.toFixed(0)); ui.set("total", r.total.toFixed(0)); ui.set("spin", rpm(wL));
    ui.badge("moves").set(r.moves ? "Car moves off" : "Stuck: left wheel spins", r.moves);
  }

  return {
    layout({ active, onPhoto }) {
      group.visible = active;
      for (const w of wheelMats) w.opacity = onPhoto ? 0.12 : w.userData.opacity;   // the real wheels show through
    },
    update(dt) {
      (p.mode === "corner" ? corner : grip)(dt);
      wheels[0].rotation.y = angL / K; wheels[1].rotation.y = angR / K;
      sides[0].rotation.y = angL; sides[1].rotation.y = angR;
      carrier.rotation.y = angC;
      const rel = (angL - angC) * Z_SIDE / Z_SPIDER;
      spiders[0].rotation.z = rel; spiders[1].rotation.z = -rel;
      chainLinks.forEach((c, i) => (c.rotation.y = (i < 2 ? angL : angR) / (i % 2 ? K : 1)));   // [left small, left big, right small, right big]
    },
  };
}

// Body and chassis models: space-frame truss, frontal crash, air suspension.
import { test } from "node:test";
import assert from "node:assert/strict";
import { solveTruss, tubeFrame, twistTest } from "../../lib/model/truss.js";
import { crushForce, simulateCrash } from "../../lib/model/crash.js";
import { airStatic, steelStatic, createCorner } from "../../lib/model/air-spring.js";
import { loadCars } from "./helpers.mjs";

test("truss: one bar stretches F·L/EA and carries F in tension", () => {
  const r = solveTruss({ nodes: [[0, 0, 0], [1000, 0, 0]], members: [{ ends: [0, 1], EA: 2e7 }],
    fixed: [{ node: 0, dof: "xyz" }, { node: 1, dof: "yz" }], loads: [{ node: 1, f: [5000, 0, 0] }] });
  assert.ok(Math.abs(r.u[1][0] - 5000 * 1000 / 2e7) < 1e-12);
  assert.ok(Math.abs(r.forces[0] - 5000) < 1e-9);
});

test("truss: a loaded triangle matches statics (apex load splits into the two legs)", () => {
  // 3-4-5 triangle in the x–z plane, y held everywhere.
  const r = solveTruss({ nodes: [[0, 0, 0], [800, 0, 0], [0, 0, 600]],
    members: [{ ends: [0, 1], EA: 1e8 }, { ends: [1, 2], EA: 1e8 }, { ends: [0, 2], EA: 1e8 }],
    fixed: [{ node: 0, dof: "xyz" }, { node: 1, dof: "yz" }, { node: 2, dof: "y" }], loads: [{ node: 2, f: [3000, 0, 0] }] });
  // Joint 2: horizontal 3000 N is carried by the hypotenuse (1→2, cos = 0.8): compression 3750 N; vertical leg 0→2 then
  // takes the hypotenuse's vertical part (0.6 · 3750 = 2250 N) in tension.
  assert.ok(Math.abs(r.forces[1] + 3750) < 1e-6);
  assert.ok(Math.abs(r.forces[2] - 2250) < 1e-6);
});

test("every space frame in the tour: cutting the side truss down for doors loses most of the twist stiffness", async () => {
  const frames = (await loadCars()).flatMap(c => c.components.filter(k => k.subsystem === "space-frame").map(k => k.params));
  assert.ok(frames.length > 0);
  for (const p of frames) {
    const [high, low] = ["high", "low"].map(door => {
      const f = tubeFrame(p.stations, p.bays.map(b => (b.door ? { ...b, door } : b)), p.EA);
      return twistTest(f, 0, p.stations.length - 1, 1000);
    });
    assert.ok(high.stiffness > 0 && Number.isFinite(high.stiffness));
    assert.ok(high.stiffness > 2 * low.stiffness, `${high.stiffness.toFixed(0)} vs ${low.stiffness.toFixed(0)} N·m/deg`);
  }
});

const mass = 1300, v0 = 50 / 3.6;
// Frontal impact into a rigid wall, one mass. Pure: no DOM, no three.js. SI units.
// The front crushes with force F(x) until the car stops; past zone.length the passenger cell itself deforms (intrusion).
// zone = { type: "crumple", force (N), length (m), ramp (m) }: folds at a nearly constant force, the safety-body idea;
//        { type: "stiff", k (N/m), length (m) }: force rises steeply with every millimetre, as in a rigid older body.
const G = 9.81;

export function crushForce(zone, cellK, x) {
  if (x <= zone.length) return zone.type === "stiff" ? zone.k * x : zone.force * Math.min(1, x / zone.ramp);
  const atEnd = zone.type === "stiff" ? zone.k * zone.length : zone.force;
  return atEnd + cellK * (x - zone.length);
}

// Returns time traces (every ms), peak and mean deceleration in g, crush, intrusion into the cell (m) and duration (s).
export function simulateCrash({ mass, v0, zone, cellK }, dt = 2e-5) {
  let x = 0, v = v0, t = 0, peak = 0, next = 0;
  const out = { t: [], x: [], a: [] };
  while (v > 0 && t < 0.5) {
    const a = crushForce(zone, cellK, x) / mass;
    peak = Math.max(peak, a);
    if (t >= next) { out.t.push(t); out.x.push(x); out.a.push(a / G); next += 1e-3; }
    v -= a * dt; x += Math.max(v, 0) * dt; t += dt;
  }
  out.t.push(t); out.x.push(x); out.a.push(0);
  return { ...out, peakG: peak / G, meanG: v0 / t / G, crush: x, intrusion: Math.max(0, x - zone.length), duration: t };
}
// Self-levelling air suspension vs a steel spring, one corner. Pure: no DOM, no three.js. SI units.
// Air spring: gauge pressure on an effective area carries the load; stiffness k = n·p_abs·A²/V rises with the load,
// so the ride frequency stays nearly constant. A steel spring keeps k and sags instead.
const PATM = 101325, G = 9.81;
const hz = (k, m) => Math.sqrt(k / m) / (2 * Math.PI);

// Static values at ride height. a = { area (m²), volume (m³), n (polytropic exponent) }.
export function airStatic(a, mass) {
  const pg = mass * G / a.area, k = (a.n ?? 1.3) * (pg + PATM) * a.area ** 2 / a.volume;
  return { pg, k, f: hz(k, mass) };
}
export const steelStatic = (k, mass, emptyMass) => ({ sag: (mass - emptyMass) * G / k, f: hz(k, mass) });

// Dynamic corner. kind "air": air spring with a levelling valve that adds or vents air while the body is off ride height.
// kind "steel": spring of rate k, preloaded to carry emptyMass at ride height. z = sag below ride height (m), + = lower.
// The valve is proportional: it moves air at up to valveRate (share of the air per second) once the body is `full` metres
// off ride height, and does nothing inside ±tol.
export function createCorner({ kind, air, k, emptyMass, damping, valveRate = 0.15, tol = 0.002, full = 0.02 }) {
  const n = air?.n ?? 1.3;
  const s = { z: 0, v: 0, C: 0, valve: "level" };
  if (kind === "air") s.C = (airStatic(air, emptyMass).pg + PATM) * air.volume ** n;   // p·Vⁿ of the air in the spring
  s.step = (mass, dt) => {
    let F;
    if (kind === "air") F = (s.C / (air.volume - air.area * s.z) ** n - PATM) * air.area;
    else F = emptyMass * G + k * s.z;
    s.v += (mass * G - F - damping * s.v) / mass * dt;
    s.z += s.v * dt;
    if (kind === "air") {
      s.valve = s.z > tol ? "filling" : s.z < -tol ? "venting" : "level";
      if (s.valve !== "level") s.C *= 1 + valveRate * Math.max(-1, Math.min(1, s.z / full)) * dt;
    }
    return s;
  };
  s.pressure = () => (kind === "air" ? s.C / (air.volume - air.area * s.z) ** n - PATM : NaN);   // gauge, Pa
  return s;
}

